/**
 * The committed strategy table is what the SOLVER emits — byte for byte.
 *
 * "Strategy tables are generated by the EV solver in
 * `scripts/generate-strategy-tables.ts`, never hand-typed" is one of this
 * project's eight absolute invariants, and until this file existed **nothing
 * asserted it**.
 *
 * `cross-validation.test.ts` is the closest thing, and it is not the same
 * claim: it compares the COMMITTED table against a published chart and lists
 * every disagreement. That catches a hand-edit only if the edit disagrees with
 * the published chart in a NEW way — an edit that moved a cell ONTO one of the
 * currently-adjudicated differences would agree with the reference, match a
 * written note, and pass every test in the repository while replacing computed
 * advice with a guess. Which is exactly what the specification forbids.
 *
 * WHY BYTE FOR BYTE rather than cell by cell. A cell comparison has to decide
 * what counts as a cell, and would quietly stop covering anything the emitter
 * later adds — the metadata block, the approximations list, the rules summary,
 * the fallback actions. Re-emitting the whole file and comparing the string
 * covers all of it and cannot go out of date. The only thing normalised is the
 * `generatedAt` timestamp, which is the one part of the file that is SUPPOSED to
 * differ between two runs; the committed file's own value is fed back in, so
 * even that is not skipped, only pinned.
 *
 * SLOW BY NATURE. This solves the six-deck chart exactly, which takes around
 * thirty seconds — the same recursion `solver.test.ts` runs. It is worth it:
 * this is the file that decides what every player is told the right play is.
 */

import { readFileSync } from "node:fs";
import { join } from "node:path";

import { beforeAll, describe, expect, it } from "vitest";

import { ARC_STANDARD_RULES } from "../../shared/blackjack/rules.js";
import { emitTableSource } from "../../scripts/generate-strategy-tables.js";
import { overallExpectation, solveChart } from "../../scripts/strategy-solver.js";
import { ARC_STANDARD_STRATEGY_TABLE } from "../../supabase/functions/_shared/strategy/generated-arc-standard-v1.js";

const TABLE_PATH = join(
  process.cwd(),
  "supabase",
  "functions",
  "_shared",
  "strategy",
  "generated-arc-standard-v1.ts",
);

/** The first line at which two texts differ, or -1. */
function firstDifferingLine(a: string, b: string): number {
  const left = a.split("\n");
  const right = b.split("\n");
  const longest = Math.max(left.length, right.length);
  for (let index = 0; index < longest; index += 1) {
    if (left[index] !== right[index]) return index;
  }
  return -1;
}

describe("the generated strategy table", () => {
  /*
   * Solved ONCE. The exact six-deck recursion is around thirty seconds, and
   * both tests below need the same output — running it twice would double the
   * cost of the suite to prove the same thing.
   */
  let committed = "";
  let emitted = "";

  beforeAll(() => {
    committed = readFileSync(TABLE_PATH, "utf8");
    const chart = solveChart(ARC_STANDARD_RULES);
    emitted = emitTableSource(
      chart,
      ARC_STANDARD_RULES,
      overallExpectation(chart, ARC_STANDARD_RULES),
      // The committed file's OWN timestamp. Feeding it back is what makes this
      // a comparison of the chart rather than of the clock.
      ARC_STANDARD_STRATEGY_TABLE.metadata.generatedAt,
    );
  }, 180_000);

  it("is exactly what the solver emits today", () => {
    const line = firstDifferingLine(committed, emitted);
    expect(
      line,
      line === -1
        ? ""
        : `line ${line + 1} differs.\n  committed: ${committed.split("\n")[line]}\n` +
          `  solver:    ${emitted.split("\n")[line]}\n` +
          `Run \`npm run strategy:generate\` — and if the solver did not change, ` +
          `this file was edited by hand, which the specification forbids.`,
    ).toBe(-1);
  });

  /**
   * THE GATE PROVES IT DISCRIMINATES.
   *
   * One cell moved by hand — the kind of edit that would still agree with the
   * published chart and sail through `cross-validation.test.ts` — must be
   * caught. `hard:16:10` is the most-argued cell in blackjack and the one an
   * editor would most plausibly "correct".
   */
  it("would notice a single cell edited by hand", () => {
    const original = committed
      .split("\n")
      .find((candidate) => candidate.includes('"hard:16:10"'));
    expect(original, "the table no longer contains hard 16 vs 10").toBeDefined();

    const flipped = original!.replace(
      /recommendedAction: "[A-Z]+"/,
      (match) => (match.includes("STAND") ? 'recommendedAction: "HIT"' : 'recommendedAction: "STAND"'),
    );
    expect(flipped, "the replacement changed nothing, so this proves nothing").not.toBe(original);

    const tampered = committed.replace(original!, flipped);
    // The SAME comparison the test above makes, against a file with one hand
    // edit in it. It must not be -1.
    const line = firstDifferingLine(tampered, emitted);
    expect(line).toBeGreaterThanOrEqual(0);
    expect(tampered.split("\n")[line]).toContain("hard:16:10");
  });
});
